package com.wansheng.visitor.guard;
import java.time.*;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component class GuardOutboxPublisher{private final GuardRepository repo;private final RabbitTemplate rabbit;private final Clock clock=Clock.systemUTC();GuardOutboxPublisher(GuardRepository r,RabbitTemplate t){repo=r;rabbit=t;}@Scheduled(fixedDelayString="${visitor.guard.outbox-delay-ms:1000}")void publish(){for(var e:repo.unpublished()){String key=switch(e.eventType()){case"VISITOR_ENTERED"->"visitor.entered";case"VISITOR_EXITED"->"visitor.exited";case"MANUAL_VISITOR_REGISTERED"->"guard.manual-visitor-registered";default->throw new IllegalStateException("unsupported event type "+e.eventType());};String json="{\"eventId\":\""+e.eventId()+"\",\"eventType\":\""+e.eventType()+"\",\"visitId\":\""+e.visitId()+"\",\"occurredAt\":\""+e.occurredAt()+"\",\"version\":1}";rabbit.convertAndSend("visitor.events",key,json);repo.published(e.id(),clock.instant());}}}
